scenario.en:
function NameField({ user }) {
  // user is undefined until the fetch resolves, then { name: "Артем" }
  const [name, setName] = useState(user?.name);
  return (
    <input
      value={name}
      onChange={(e) => setName(e.target.value)}
    />
  );
}

